class Solution { public int getMaxRepetitions(String s1, int n1, String s2, int n2) { int[] count = new int[s2.length() + 1]; int[] nextIndex = new int[s2.length() + 1]; int s1Count = 0, s2Count = 0, index = 0; while (s1Count < n1) { s1Count++; for (int i = 0; i < s1.length(); i++) { if (s1.charAt(i) == s2.charAt(index)) { index++; if (index == s2.length()) { s2Count++; index = 0; } } } if (count[index] != 0) { int prevS1Count = count[index]; int prevS2Count = nextIndex[index]; int cycleS1 = s1Count - prevS1Count; int cycleS2 = s2Count - prevS2Count; int remainingS1 = n1 - s1Count; s2Count += (remainingS1 / cycleS1) * cycleS2; s1Count += (remainingS1 / cycleS1) * cycleS1; count = new int[s2.length() + 1]; } else { count[index] = s1Count; nextIndex[index] = s2Count; } } return s2Count / n2; } }